// Décodage JSON-stat 2.0 → une observation par ligne, multi-zones.
// Le décodeur du pilote gérait déjà plusieurs zones ; seule change la référence d'audit.
const resp = $('API Eurostat (sts_inpr_m, NACE C29)').first().json;
const valeurs = resp.value ?? {};
const dims = resp.id ?? [];
const tailles = resp.size ?? [];

const posTemps = dims.indexOf('time');
const posGeo   = dims.indexOf('geo');
if (posTemps < 0) {
  throw new Error('Réponse Eurostat sans dimension temporelle : structure inattendue, collecte interrompue.');
}

function libelles(dimension) {
  const index = resp.dimension?.[dimension]?.category?.index ?? {};
  return Object.keys(index).sort((a, b) => index[a] - index[b]);
}
const periodes = libelles('time');
const zones    = libelles('geo');

function coordonnees(plat) {
  const c = new Array(tailles.length);
  for (let d = tailles.length - 1; d >= 0; d--) {
    c[d] = plat % tailles[d];
    plat = Math.floor(plat / tailles[d]);
  }
  return c;
}

const runId  = $('Ouvrir le run').first().json.run_id;
const rawRef = '/data/staging/A5_eurostat_multigeo_run' + runId + '.json';

const out = [];
for (const [cle, v] of Object.entries(valeurs)) {
  if (v === null || v === undefined) continue;
  const c = coordonnees(Number(cle));
  const periode = periodes[c[posTemps]];
  const zone    = posGeo >= 0 ? (zones[c[posGeo]] ?? 'EU27_2020') : 'EU27_2020';
  if (!periode) continue;
  out.push({ json: {
    indicator_id: 'A5',
    run_id: runId,
    period: periode,
    geo: zone,
    value: Number(v),
    obtained_by: 'etl',
    validation_status: 'valide_source',
    raw_ref: rawRef
  } });
}

if (out.length === 0) {
  throw new Error('Aucune observation extraite : vérifier les codes de dimension de la requête Eurostat.');
}
// Tri zone puis période : les contrôles qualité lisent des séries continues par zone.
out.sort((a, b) => (a.json.geo + '|' + a.json.period).localeCompare(b.json.geo + '|' + b.json.period));
return out;

// Contrôles qualité déterministes (§ 10.2, couche 3) — version multi-zones.
// CORRECTION vs pilote : la mémoire de variation est tenue PAR ZONE. La version
// à séquence unique aurait comparé la dernière valeur d'un pays à la première
// du suivant et écarté des observations légitimes — défaut détecté à la revue
// du 06.08.2026, avant exécution.
const FENETRE_DEBUT = '2023';
const SEUIL_VARIATION_ANORMALE = 50;   // en %, entre deux périodes consécutives d'une même zone

const obs = $input.all().map(i => i.json);
const retenues = [];
const ecartees = [];
const precedentes = new Map();          // zone → dernière valeur retenue

for (const o of obs) {
  const motifs = [];
  if (!Number.isFinite(o.value))                          motifs.push('valeur non numérique');
  if (!/^\d{4}(-(\d{2}|Q\d))?$/.test(o.period))           motifs.push('format de période invalide');
  if (o.period < FENETRE_DEBUT)                           motifs.push("hors fenêtre d'historique de trois ans");
  if (o.value <= 0)                                       motifs.push('indice nul ou négatif');
  const prec = precedentes.get(o.geo);
  if (prec !== undefined && prec !== 0) {
    const variation = Math.abs((o.value - prec) / prec * 100);
    if (variation > SEUIL_VARIATION_ANORMALE)             motifs.push('variation anormale de ' + variation.toFixed(1) + ' % (zone ' + o.geo + ')');
  }
  if (motifs.length) { ecartees.push({ ...o, motifs }); }
  else { retenues.push(o); precedentes.set(o.geo, o.value); }
}

if (retenues.length === 0) {
  throw new Error('Toutes les observations ont été écartées par les contrôles qualité : ' + JSON.stringify(ecartees.slice(0, 3)));
}

const bilan = { retenues: retenues.length, ecartees: ecartees.length, zones: [...new Set(retenues.map(o => o.geo))].length, detail_ecartees: ecartees };
return retenues.map(o => ({ json: { ...o, _bilan: bilan } }));
